        "td",
        {
          colSpan: columns.length || 7,
          style: {
            textAlign: "center",
            border: "none",
            height: "400px"
          }
        },
        React.createElement(
          "div",
          { className: "empty-state" },
          React.createElement(EmptyIcon, null),
          React.createElement(
            "div",
            { className: "empty-text" },
            "No Records Found"
          ),
          React.createElement(
            "div",
            {
              style: {
                fontSize: "13px",
                marginTop: "8px"
              }
            },
            "Try adjusting your search criteria."
          )
        )
      )
    );

  // ================= DASHBOARD UI =================

  return React.createElement(
    "div",
    { className: "widget-container" },

    React.createElement(
      "div",
      { className: "dashboard-header" },

      React.createElement(
        "h1",
        { className: "header-title" },
        title
      ),

      React.createElement(
        "div",
        { className: "header-actions" },

        React.createElement(
          "div",
          { className: "search-container" },
          React.createElement(SearchIcon, null),
          React.createElement("input", {
            type: "text",
            className: "search-input",
            placeholder: "Search...",
            value: inputVal,
            onChange: (e) => setInputVal(e.target.value)
          })
        ),

        React.createElement(
          "button",
          {
            className: "export-btn",
            onClick: () => exportToCSV(sortedData, columns),
            disabled: sortedData.length === 0,
            title: "Export to CSV"
          },
          React.createElement(DownloadIcon, null),
          React.createElement("span", null, "Export")
        )
      )
    ),

    React.createElement(
      "div",
      { className: "table-wrapper" },

      React.createElement(
        "table",
        { className: "pr-table" },

        React.createElement(
          "thead",
          null,
          React.createElement(
            "tr",
            null,
            columns.map((col) =>
              React.createElement(
                "th",
                {
                  key: col.key,
                  onClick: () =>
                    col.sortable !== false
                      ? handleSort(col.key)
                      : null,
                  style: {
                    ...(col.type === "currency"
                      ? { textAlign: "right" }
                      : {}),
                    cursor:
                      col.sortable !== false ? "pointer" : "default"
                  }
                },
                col.label,
                " ",
                col.sortable !== false &&
                  React.createElement(
                    "span",
                    { className: "sort-icon" },
                    getSortIcon(col.key)
                  )
              )
            )
          )
        ),

        React.createElement(
          "tbody",
          null,

          isLoading ? renderSkeletons() : null,

          !isLoading && paginatedData.length === 0
            ? renderEmptyState()
            : null,

          !isLoading &&
            paginatedData.map((row, idx) =>
              React.createElement(
                "tr",
                {
                  key: idx,
                  onClick: () => handleRowClick(row)
                },
                columns.map((col) =>
                  React.createElement(
                    "td",
                    {
                      key: col.key,
                      className:
                        col.type === "currency" ? "col-val" : ""
                    },
                    renderCell(row, col)
                  )
                )
              )
            )
        )
      )
    ),

    // ================= PAGINATION FOOTER =================
    // Right-aligned pagination; all other functionality remains unchanged.
    React.createElement(
      "div",
      {
        className: "pagination-container",
        style: {
          justifyContent: "flex-end",
          alignItems: "center",
          gap: "24px",
          flexWrap: "wrap"
        }
      },

      React.createElement(
        "div",
        { className: "page-info" },

        "Showing ",

        totalItems === 0
          ? 0
          : (currentPage - 1) * rowsPerPage + 1,

        "–",

        Math.min(currentPage * rowsPerPage, totalItems),

        " of ",

        totalItems,

        " records"
      ),

      React.createElement(
        "div",
        {
          className: "page-controls",
          style: {
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            gap: "16px"
          }
        },

        React.createElement(
          "div",
          { className: "rows-selector" },

          "Rows per page:",

          React.createElement(
            "select",
            {
              className: "rows-select",
              value: rowsPerPage,
              onChange: (e) => {
                setRowsPerPage(Number(e.target.value));
                setCurrentPage(1);
              }
            },

            React.createElement("option", { value: 10 }, "10"),
            React.createElement("option", { value: 20 }, "20"),
            React.createElement("option", { value: 50 }, "50"),
            React.createElement("option", { value: 100 }, "100")
          )
        ),

        React.createElement(
          "div",
          { className: "page-buttons" },

          React.createElement(
            "button",
            {
              className: "page-btn",
              disabled: currentPage === 1,
              onClick: () => setCurrentPage((p) => p - 1)
            },
            "←"
          ),

          React.createElement(
            "button",
            { className: "page-btn active" },
            currentPage
          ),

          React.createElement(
            "button",
            {
              className: "page-btn",
              disabled: currentPage >= totalPages,
              onClick: () => setCurrentPage((p) => p + 1)
            },
            "→"
          )
        )
      )
    )
  );
}

// ================= APP INITIALIZATION =================

appsmith.onReady(() => {
  const container = document.getElementById("root");

  if (container) {
    container.innerHTML = "";

    ReactDOM.render(
      React.createElement(DynamicDashboard, null),
      container
    );
  }
});
